// FABi CMS icons: the design's icon set (24 × 24 grid; line = 2px stroke, solid = fill) as React components,
// generated by scripts/gen-fabi-icons.mjs (user 2026-10-13: line + solid, "Home03Line / Home03Solid",
// subpath @fabi/ui/fabi-icons). Each icon renders like an @ant-design/icons icon: a span with the icon
// prefix class (fabi-icon), so it lines up in every antd `icon` prop (Button, Menu, Input…), sized 1em and
// coloured currentColor. The SVG markup is the design's export, unchanged except black → currentColor.
import { ConfigProvider } from 'antd'
import { forwardRef, useContext } from 'react'
import type { ForwardRefExoticComponent, HTMLAttributes, RefAttributes } from 'react'

export type FabiIconStyle = 'line' | 'solid'

export interface FabiIconProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> {
  /** Width and height (default 1em: follows the font size, like antd icons) */
  size?: number | string
  /** Accessible name (or pass aria-label / aria-labelledby). Without one the icon is decorative (aria-hidden),
   *  the usual case next to a label */
  title?: string
  /** Rotate continuously, e.g. a loading indicator (antd's `spin`) */
  spin?: boolean
}

export type FabiIcon = ForwardRefExoticComponent<FabiIconProps & RefAttributes<HTMLSpanElement>> & {
  /** Name in the design, e.g. "home-03-line" (line) / "home-03" (solid) */
  readonly iconName: string
  readonly iconStyle: FabiIconStyle
}

/** One icon component from the design's SVG markup (the children of its 24 × 24 <svg>) */
export function createFabiIcon(displayName: string, iconName: string, iconStyle: FabiIconStyle, markup: string): FabiIcon {
  const Icon = forwardRef<HTMLSpanElement, FabiIconProps>(function FabiIconComponent({ size = '1em', title, spin, className, ...rest }, ref) {
    const { iconPrefixCls } = useContext(ConfigProvider.ConfigContext)
    const cls = [iconPrefixCls, `${iconPrefixCls}-${iconName}`, spin && `${iconPrefixCls}-spin`, className].filter(Boolean).join(' ')
    const label = title ?? rest['aria-label']
    const named = Boolean(label || rest['aria-labelledby'])
    return (
      <span ref={ref} role={named ? 'img' : undefined} aria-hidden={named ? undefined : true} className={cls} {...rest} aria-label={label}>
        <svg width={size} height={size} viewBox="0 0 24 24" fill="none" focusable="false" dangerouslySetInnerHTML={{ __html: markup }} />
      </span>
    )
  })
  Icon.displayName = displayName
  return Object.assign(Icon, { iconName, iconStyle })
}
